export const TIPS: Tip[] = [
  // === BUDGETING (1-20) ===
  { id: '1', title: 'The 50/30/20 Rule', emoji: '📊', content: 'Split your income: 50% for needs (rent, food, transport), 30% for wants (entertainment, dining out), and 20% for savings. This simple framework keeps your budget balanced.', category: 'budgeting', difficulty: 'beginner', isFeatured: true, potentialSaving: 500, actionSteps: ['Calculate your monthly income after tax', 'List all fixed expenses (needs)', 'Set a fun-money limit (wants)', 'Automate your 20% savings transfer on payday'], tags: ['essential', 'beginner-friendly', 'framework'] },
  { id: '2', title: 'Subscription Audit', emoji: '🔍', content: 'The average student pays for 4-6 subscriptions they barely use. Pull bank statements, list every debit order, and cancel anything unused in 30 days. One audit can save R200-R600/month instantly.', category: 'budgeting', difficulty: 'beginner', potentialSaving: 600, actionSteps: ['Pull your last 3 months of bank statements', 'Highlight every recurring debit order', 'Rate each: use daily / weekly / never', 'Cancel everything rated "never" today'], tags: ['quick-win', 'audit', 'subscriptions'] },
  { id: '3', title: 'Zero-Based Budgeting', emoji: '🎯', content: 'Give every rand a job. Income minus all planned spending should equal R0. This doesn\'t mean spend everything — allocate every rand including savings. People who zero-base spend 15-20% less.', category: 'budgeting', difficulty: 'intermediate', potentialSaving: 800, actionSteps: ['List your exact monthly income', 'Assign every rand to a category', 'Include "savings" as mandatory', 'Track daily and adjust weekly'], tags: ['advanced-budgeting', 'discipline'] },
  { id: '4', title: 'The Envelope System (Digital)', emoji: '✉️', content: 'Allocate cash to virtual "envelopes" for each spending category. When empty, stop spending. Capitec and FNB allow sub-accounts that work like digital envelopes.', category: 'budgeting', difficulty: 'beginner', potentialSaving: 700, actionSteps: ['Create 4-5 spending categories', 'Set a monthly limit for each', 'Use separate bank pockets or sub-accounts', 'Roll over unused amounts to savings'], tags: ['cash-flow', 'discipline', 'banking'] },
  { id: '5', title: 'Track Every Rand for 30 Days', emoji: '📝', content: 'Before optimising, you need data. Track every expense for one full month. Most people find R500-R1,500/month in "invisible" spending. Awareness alone reduces spending by 10-15%.', category: 'budgeting', difficulty: 'beginner', potentialSaving: 500, actionSteps: ['Use this app or a notebook', 'Record every purchase immediately', 'Categorise at end of each day', 'Identify your top 3 "leak" categories'], tags: ['awareness', 'data', 'first-step'] },
  { id: '6', title: 'Bill Negotiation Scripts', emoji: '📞', content: '"I\'ve been a loyal customer and found a better deal elsewhere — can you match it?" works 60% of the time. Target: cell phone, insurance, internet. SA providers have retention departments for this.', category: 'budgeting', difficulty: 'intermediate', potentialSaving: 1200, actionSteps: ['List all monthly service providers', 'Research competitor prices', 'Call and ask for "retention department"', 'Mention the competitor offer'], tags: ['negotiation', 'bills', 'phone'] },
  { id: '7', title: 'Cash-Only Weekends', emoji: '💵', content: 'Withdraw a fixed cash amount for weekend spending. When it\'s gone, it\'s gone. Studies show people spend 12-18% less with physical cash because the "pain of paying" is stronger.', category: 'budgeting', difficulty: 'beginner', potentialSaving: 400, actionSteps: ['Decide on a weekend budget', 'Withdraw cash on Friday', 'Leave your card at home', 'Track what you spent'], tags: ['psychology', 'weekend', 'cash'] },
  { id: '8', title: 'Automate Your Bills', emoji: '⚡', content: 'Set up debit orders for all recurring expenses on payday. This prevents late fees, removes decision fatigue, and ensures essentials are covered before discretionary spending starts.', category: 'budgeting', difficulty: 'beginner', potentialSaving: 300, actionSteps: ['List all recurring bills', 'Set up debit orders for each', 'Schedule them for 1-2 days after payday', 'Check monthly that amounts are correct'], tags: ['automation', 'bills', 'stress-free'] },
  { id: '9', title: 'The Price-Per-Use Method', emoji: '🧮', content: 'Before buying, calculate cost per use. A R600 jacket worn 100 times = R6/use (great). A R200 trendy top worn 3 times = R67/use (terrible). This simple math kills impulse buys.', category: 'budgeting', difficulty: 'beginner', potentialSaving: 500, actionSteps: ['Before buying, estimate how many times you\'ll use it', 'Divide price by expected uses', 'Compare: is cost-per-use under R10?', 'If not, reconsider the purchase'], tags: ['mindset', 'shopping', 'value'] },
  { id: '10', title: 'Weekly Budget Check-In', emoji: '📅', content: 'Every Sunday, spend 10 minutes reviewing the week: what you spent, what\'s left, what\'s coming up. This one habit keeps your budget on track better than any app feature.', category: 'budgeting', difficulty: 'beginner', potentialSaving: 400, actionSteps: ['Set a Sunday reminder at 7pm', 'Review all spending from the week', 'Check remaining budget for each category', 'Plan for next week\'s known expenses'], tags: ['habit', 'review', 'weekly'] },
  { id: '11', title: 'The 10% Rule for Raises', emoji: '📈', content: 'When your income increases, save at least half the raise before lifestyle inflation kicks in. Got a R1,000 raise? Save R500, enjoy R500. This builds wealth invisibly.', category: 'budgeting', difficulty: 'intermediate', potentialSaving: 600, actionSteps: ['Calculate your new income after raise', 'Immediately increase savings by 50% of the difference', 'Adjust budget with the remaining 50%', 'Repeat with every income increase'], tags: ['income', 'lifestyle-inflation', 'wealth'] },
  { id: '12', title: 'Meal Budget Strategy', emoji: '🍽️', content: 'Allocate a daily food budget (e.g., R80/day = R2,400/mo). This forces creativity: meal prep on cheap days, treat yourself on budget days. Track daily to stay aware.', category: 'budgeting', difficulty: 'beginner', potentialSaving: 600, actionSteps: ['Set a daily food budget', 'Track every food purchase', 'Meal prep 3-4 days per week', 'Use "saved" days for treats'], tags: ['food', 'daily', 'tracking'] },
  { id: '13', title: 'Annual Expense Planning', emoji: '🗓️', content: 'List all yearly expenses (car service, registration, insurance, holiday gifts) and divide by 12. Save that monthly so you\'re never caught off guard by "unexpected" annual bills.', category: 'budgeting', difficulty: 'intermediate', potentialSaving: 800, actionSteps: ['List all annual/semi-annual expenses', 'Add up the total', 'Divide by 12', 'Set up a monthly transfer to a sinking fund'], tags: ['planning', 'annual', 'sinking-fund'] },
  { id: '14', title: 'The Wants vs Needs List', emoji: '📋', content: 'Before month-end, write two lists: needs (must pay) and wants (nice to have). Pay needs first, then allocate remaining to wants by priority. Simple but eliminates 80% of budget stress.', category: 'budgeting', difficulty: 'beginner', potentialSaving: 300, actionSteps: ['List all needs (rent, food, transport)', 'List all wants (entertainment, dining)', 'Pay needs first', 'Rank wants by importance', 'Fund wants in priority order'], tags: ['prioritization', 'simple', 'stress-free'] },
  { id: '15', title: 'Spending Triggers Awareness', emoji: '🧠', content: 'Identify what makes you overspend: boredom, stress, social pressure, payday excitement? Once you know your triggers, you can create alternative responses. Stressed? Walk, don\'t shop.', category: 'budgeting', difficulty: 'intermediate', potentialSaving: 800, actionSteps: ['Track emotions when you spend impulsively', 'Identify your top 3 spending triggers', 'Create alternative actions for each trigger', 'Practice for 30 days'], tags: ['psychology', 'awareness', 'habits'] },
  { id: '16', title: 'Budget With a Partner', emoji: '👫', content: 'If you share expenses with a partner or flatmate, budget together monthly. Split costs fairly, use a shared app or spreadsheet, and agree on shared vs personal spending categories.', category: 'budgeting', difficulty: 'intermediate', potentialSaving: 500, actionSteps: ['List all shared expenses', 'Agree on a fair split method', 'Use a shared tracking tool', 'Review together monthly'], tags: ['shared', 'partner', 'communication'] },
  { id: '17', title: 'The Anti-Budget Method', emoji: '🎲', content: 'Hate detailed budgeting? Try this: save your target amount first (pay yourself first), pay bills, then spend the rest guilt-free. No tracking needed. Simple and effective for budget-haters.', category: 'budgeting', difficulty: 'beginner', potentialSaving: 400, actionSteps: ['Set your savings target (e.g., 20% of income)', 'Automate savings transfer on payday', 'Pay all bills via debit order', 'Spend the rest however you want'], tags: ['simple', 'low-maintenance', 'freedom'] },
  { id: '18', title: 'Grocery List Discipline', emoji: '📃', content: 'Never shop without a list. People who shop with lists spend 23% less than those who browse. Write your list at home, stick to it in-store, and never shop hungry.', category: 'budgeting', difficulty: 'beginner', potentialSaving: 500, actionSteps: ['Plan meals for the week', 'Write a grocery list based on meal plan', 'Check what you already have at home', 'Stick to the list — no extras', 'Never shop hungry'], tags: ['groceries', 'discipline', 'shopping'] },
  { id: '19', title: 'Financial Calendar', emoji: '📆', content: 'Create a calendar with all money events: paydays, bill due dates, savings goals milestones. Visual planning prevents "where did my money go?" syndrome.', category: 'budgeting', difficulty: 'beginner', potentialSaving: 300, actionSteps: ['Mark all paydays', 'Add all bill due dates', 'Add savings goal checkpoints', 'Review at start of each month'], tags: ['planning', 'visual', 'organization'] },
  { id: '20', title: 'The Buffer Account', emoji: '🛡️', content: 'Keep one month\'s expenses as a buffer in your main account. This prevents overdraft fees and gives breathing room. Build it slowly: R500/month until you have a full month\'s buffer.', category: 'budgeting', difficulty: 'intermediate', potentialSaving: 600, actionSteps: ['Calculate one month of essential expenses', 'Start saving R500/month toward your buffer', 'Keep it in your main account', 'Never dip below this amount'], tags: ['safety', 'buffer', 'overdraft'] },

  // === STUDENT (21-40) ===
  { id: '21', title: 'Meal Prep Like a Pro', emoji: '🍱', content: 'Cook meals in bulk on Sundays. Students who meal prep save R800-R1,200/month vs buying takeaways daily. A full week\'s groceries: R250-R400 vs R80-R120/day on takeaways.', category: 'student', difficulty: 'beginner', isFeatured: true, potentialSaving: 1000, actionSteps: ['Plan 5 meals for the week', 'Buy ingredients in bulk', 'Cook 2-3 large batches on Sunday', 'Portion into labelled containers'], tags: ['food', 'weekly-habit', 'cooking'] },
  { id: '22', title: 'Textbook Hacks', emoji: '📚', content: 'Never buy new textbooks at full price. A R800 textbook can be found for R200-R300 secondhand. Check Takealot, campus boards, WhatsApp groups, or use LibGen for digital copies.', category: 'student', difficulty: 'beginner', potentialSaving: 2000, actionSteps: ['Check if the library has reserve copies', 'Search Takealot, Facebook Marketplace', 'Join campus book exchange groups', 'Split textbook costs with study partners'], tags: ['academic', 'quick-win', 'textbooks'] },
  { id: '23', title: 'Student Discount Everything', emoji: '🎓', content: 'Spotify Student R30/mo, Apple Music R35/mo, free Microsoft Office 365, free GitHub Pro, free Canva Pro. Always ask "do you have a student discount?" — worst case they say no.', category: 'student', difficulty: 'beginner', potentialSaving: 400, actionSteps: ['Ensure your student card is current', 'Sign up for all student plan services', 'Get free software via university email', 'Always ask for student discounts'], tags: ['discounts', 'easy', 'free-stuff'] },
  { id: '24', title: 'Transport Savings', emoji: '🚌', content: 'Uber from Braamfontein to Sandton: R80-R120. MyCiTi bus: R15. Walking/cycling under 3km saves R500+/month. Lift clubs split fuel 3-4 ways.', category: 'student', difficulty: 'beginner', potentialSaving: 700, actionSteps: ['Calculate monthly transport spend', 'Compare Uber vs bus vs walking', 'Join campus lift clubs', 'Buy monthly public transport passes'], tags: ['transport', 'daily', 'commute'] },
  { id: '25', title: 'Free Campus Resources', emoji: '🏫', content: 'Your fees include: free Wi-Fi, free printing quotas, free counselling, career services, writing centres. UCT, Wits, Stellenbosch, UP all offer these — most students never use them.', category: 'student', difficulty: 'beginner', potentialSaving: 500, actionSteps: ['Check your university student services website', 'Use campus Wi-Fi to save on data', 'Use your free printing quota', 'Attend free career workshops'], tags: ['free', 'campus', 'resources'] },
  { id: '26', title: 'Res vs Digs Cost Analysis', emoji: '🏠', content: 'University res seems expensive but includes electricity, Wi-Fi, water, security, proximity. Off-campus at R3,500/mo + utilities + transport often costs MORE. Do the full comparison.', category: 'student', difficulty: 'intermediate', potentialSaving: 3000, actionSteps: ['List ALL costs of current living situation', 'Include hidden costs: electricity, WiFi, transport', 'Compare with 2-3 alternatives', 'Factor in commute time cost'], tags: ['accommodation', 'analysis', 'big-decision'] },
  { id: '27', title: 'Data & Airtime Savings', emoji: '📱', content: 'Stop buying daily data bundles — 3-5x more expensive. Vodacom 1GB daily = R450/mo. 30-day 10GB = R149. Download lectures on Wi-Fi for offline viewing.', category: 'student', difficulty: 'beginner', potentialSaving: 350, actionSteps: ['Check monthly data spend', 'Switch to monthly data deals', 'Download content on Wi-Fi', 'Use WhatsApp calls instead of regular calls'], tags: ['data', 'phone', 'quick-win'] },
  { id: '28', title: 'NSFAS & Bursary Maximization', emoji: '🎒', content: 'If you receive NSFAS: tuition, accommodation, food (R15,000/yr), books (R5,460/yr), transport allowances. Many students don\'t claim all. Also apply for 10+ external bursaries.', category: 'student', difficulty: 'intermediate', potentialSaving: 5000, actionSteps: ['Review your NSFAS allocation letter', 'Ensure you\'re claiming all allowances', 'Apply to external bursaries on bursaries.co.za', 'Keep all receipts for claims'], tags: ['funding', 'bursaries', 'NSFAS'] },
  { id: '29', title: 'Study Group Savings', emoji: '👥', content: 'Share textbooks, split Chegg subscriptions, take turns buying snacks for group sessions. A study group of 4 saves each member R200-R500/month on resources.', category: 'student', difficulty: 'beginner', potentialSaving: 400, actionSteps: ['Form a study group of 3-5 people', 'Share textbook costs', 'Split subscription services', 'Rotate hosting duties'], tags: ['sharing', 'study', 'social'] },
  { id: '30', title: 'Campus Food Deals', emoji: '🌮', content: 'Most campus cafeterias have daily specials (R25-R40 meals). Bring your own lunch 3 days, eat specials 2 days. Follow your SRC for free pizza at events — it\'s more common than you think.', category: 'student', difficulty: 'beginner', potentialSaving: 500, actionSteps: ['Learn your cafeteria\'s daily specials', 'Pack lunch at least 3 days per week', 'Follow SRC social media for free food events', 'Keep snacks in your bag to avoid impulse buys'], tags: ['food', 'campus', 'deals'] },
  { id: '31', title: 'Second-Hand Fashion', emoji: '👗', content: 'Thrift stores, vintage shops, and apps like Yaga have amazing finds for 70-90% off retail. Your style doesn\'t need to cost a fortune. R100 at a thrift shop buys what R500 buys at retail.', category: 'student', difficulty: 'beginner', potentialSaving: 600, actionSteps: ['Find thrift stores near campus', 'Download Yaga or check Facebook Marketplace', 'Set a monthly clothing budget', 'Sell clothes you don\'t wear anymore'], tags: ['fashion', 'thrift', 'sustainable'] },
  { id: '32', title: 'Free Software for Students', emoji: '💻', content: 'GitHub Student Developer Pack: free domains, cloud hosting, JetBrains IDEs. Microsoft 365 free via uni email. Adobe Creative Cloud 60% off. Autodesk free for students. Worth R10,000+/year.', category: 'student', difficulty: 'beginner', potentialSaving: 800, actionSteps: ['Apply for GitHub Student Pack', 'Activate Microsoft 365 with university email', 'Check Adobe student pricing', 'Explore all free tools at education.github.com'], tags: ['software', 'free', 'tech'] },
  { id: '33', title: 'Vacation Job Strategy', emoji: '☀️', content: 'December/June holidays: temp jobs pay R80-R150/hour. 4 weeks × 40 hours × R100 = R16,000. Apply early (September for Dec jobs). Retail, hospitality, and call centres always hire seasonal.', category: 'student', difficulty: 'beginner', potentialSaving: 8000, actionSteps: ['Start applying 2 months before holidays', 'Check Indeed, PNet, and campus career services', 'Target retail and hospitality (always hiring)', 'Save at least 50% of holiday earnings'], tags: ['income', 'seasonal', 'holiday'] },
  { id: '34', title: 'Health Centre vs Private Doctor', emoji: '🏥', content: 'University health centres offer free or R50 consultations. Private GP: R500-R800. Campus pharmacy is often 30-50% cheaper. Use university psychological services — they\'re free and confidential.', category: 'student', difficulty: 'beginner', potentialSaving: 600, actionSteps: ['Locate your campus health centre', 'Register as a patient', 'Use campus pharmacy for prescriptions', 'Know the emergency after-hours number'], tags: ['health', 'free', 'campus'] },
  { id: '35', title: 'Printing & Stationery Savings', emoji: '🖨️', content: 'Print double-sided, use campus free quota first, share notes digitally. A R3,000/year printing bill drops to R500 with smart habits. Use Notion or OneNote instead of buying notebooks.', category: 'student', difficulty: 'beginner', potentialSaving: 500, actionSteps: ['Check your free printing allocation', 'Print double-sided always', 'Share notes via Google Drive', 'Use digital note-taking apps'], tags: ['stationery', 'printing', 'digital'] },
  { id: '36', title: 'Flatmate Financial Rules', emoji: '🤝', content: 'Living with others? Set rules day one: how to split bills, shared grocery systems, utility payment responsibilities. Apps like Splitwise track who owes what without awkward conversations.', category: 'student', difficulty: 'intermediate', potentialSaving: 400, actionSteps: ['Have a money conversation before moving in', 'Agree on bill-splitting method', 'Use Splitwise or a shared spreadsheet', 'Review shared expenses monthly'], tags: ['shared-living', 'communication', 'flatmates'] },
  { id: '37', title: 'Entertainment Exchange', emoji: '🎬', content: 'Instead of everyone paying for Netflix, Spotify, etc., each friend pays for ONE service and shares. 4 friends × 1 service each = 4 services for the price of 1. Saves R200-R400/month.', category: 'student', difficulty: 'beginner', potentialSaving: 300, actionSteps: ['Form a sharing group of 3-5 friends', 'Each person subscribes to one service', 'Share family/duo plans where possible', 'Rotate who pays if sharing isn\'t allowed'], tags: ['sharing', 'entertainment', 'subscriptions'] },
  { id: '38', title: 'Exam Prep Without Spending', emoji: '📖', content: 'Free resources: Khan Academy, YouTube (Professor Leonard, 3Blue1Brown), past papers from your library, study groups. You don\'t need expensive tutors for every subject.', category: 'student', difficulty: 'beginner', potentialSaving: 500, actionSteps: ['Find free YouTube channels for your subjects', 'Download past papers from the library', 'Form study groups for difficult modules', 'Only pay for tutoring as last resort'], tags: ['studying', 'free', 'academic'] },
  { id: '39', title: 'Gym Alternatives', emoji: '🏋️', content: 'University gym: usually free with student card. No campus gym? YouTube workout channels (THENX, Chloe Ting, Athlean-X) + a park = free fitness. Planet Fitness is R99/mo if you must.', category: 'student', difficulty: 'beginner', potentialSaving: 500, actionSteps: ['Check if campus gym is included in fees', 'Try YouTube workout programs', 'Use outdoor spaces for exercise', 'Only pay for gym if campus option unavailable'], tags: ['fitness', 'free', 'health'] },
  { id: '40', title: 'Part-Time Work Balance', emoji: '⚖️', content: 'Working 15-20 hours/week is optimal — enough income without hurting grades. More than 25 hours/week correlates with lower GPAs. Choose jobs aligned with your field when possible.', category: 'student', difficulty: 'intermediate', potentialSaving: 3000, actionSteps: ['Cap work at 20 hours during term', 'Prioritize study during exams', 'Choose jobs with flexible scheduling', 'Track hours vs grades to find your balance'], tags: ['work-life', 'balance', 'grades'] },

  // === SAVING (41-58) ===
  { id: '41', title: 'Emergency Fund Strategy', emoji: '🛡️', content: 'Target: 3-6 months basic expenses. Start with R200/month. In a Money Market account at 8-9%, it grows while you sleep. This prevents debt when life happens.', category: 'saving', difficulty: 'intermediate', isFeatured: true, potentialSaving: 6000, actionSteps: ['Calculate monthly essentials', 'Set a 3-month target minimum', 'Open a Money Market account', 'Automate R200-R500 monthly'], tags: ['critical', 'long-term', 'safety-net'] },
  { id: '42', title: 'Pay-Yourself-First Method', emoji: '💰', content: 'On payday, transfer savings BEFORE spending on anything else. Most people save "leftovers" — usually nothing. Even R300/month becomes R3,600/year + interest.', category: 'saving', difficulty: 'beginner', potentialSaving: 3600, actionSteps: ['Set a fixed savings amount (10% of income)', 'Set up debit order for payday', 'Transfer to a separate account', 'Increase by R50 every 3 months'], tags: ['automation', 'habit', 'essential'] },
  { id: '43', title: 'The Savings Snowball', emoji: '⛄', content: 'Start tiny: R500 goal. The dopamine hit motivates bigger goals. R500 → R1,000 → R5,000 → R10,000. Small early wins are the #1 predictor of long-term saving success.', category: 'saving', difficulty: 'beginner', potentialSaving: 2000, actionSteps: ['Set first goal: R500', 'Save R20-R50/week', 'Celebrate when you hit it', 'Immediately set next goal'], tags: ['motivation', 'psychology', 'goals'] },
  { id: '44', title: 'Round-Up Savings', emoji: '🔄', content: 'Round every purchase to nearest R10. R37 coffee → R40, save R3. Averages R15-R30/day = R450-R900/month. Capitec and TymeBank have built-in round-up features.', category: 'saving', difficulty: 'beginner', potentialSaving: 700, actionSteps: ['Enable bank app round-up feature', 'Or manually transfer round-ups daily', 'Don\'t touch the account for 3 months', 'Be amazed at how much accumulates'], tags: ['micro-saving', 'automation', 'painless'] },
  { id: '45', title: 'Savings Account Interest Comparison', emoji: '🏦', content: 'Standard savings: 3-4%. Money Market: 7-9%. Fixed deposits: 8-11%. African Bank Money Market pays 9.25%. TymeBank GoalSave: 9%. That difference on R10,000 = R300-R700/year extra.', category: 'saving', difficulty: 'intermediate', potentialSaving: 500, actionSteps: ['Check your current interest rate', 'Compare African Bank, TymeBank, Discovery, Capitec', 'Move savings to highest-interest option', 'Re-compare rates every 6 months'], tags: ['interest', 'banking', 'optimisation'] },
  { id: '46', title: 'The 30-Day Savings Rule', emoji: '📅', content: 'Want something non-essential? Write it down and wait 30 days. If you still want it and can afford it, buy it. This eliminates 80% of impulse purchases and saves thousands yearly.', category: 'saving', difficulty: 'beginner', potentialSaving: 1500, actionSteps: ['Create a "want list" on your phone', 'Add items with dates', 'Wait 30 full days', 'Buy only if still wanted AND budgeted for'], tags: ['impulse-control', 'discipline', 'mindset'] },
  { id: '47', title: 'Savings Jar Visual Tracker', emoji: '🫙', content: 'Visual progress is powerful. Use a jar, chart, or app to see savings grow. Color in a thermometer as you save toward a goal. Seeing progress keeps motivation high when willpower is low.', category: 'saving', difficulty: 'beginner', potentialSaving: 500, actionSteps: ['Choose a visual tracking method', 'Set clear milestone markers', 'Update it every time you save', 'Put it somewhere you see daily'], tags: ['visual', 'motivation', 'psychology'] },
  { id: '48', title: 'The Spare Change Challenge', emoji: '🪙', content: 'Save all R5 coins for a month. Average result: R300-R500. Save all R2 coins too and you\'ll hit R600+. It\'s money you barely notice spending but adds up fast in a jar.', category: 'saving', difficulty: 'beginner', potentialSaving: 500, actionSteps: ['Get a jar or container', 'Save all R5 and R2 coins', 'Don\'t count until month end', 'Deposit into savings account'], tags: ['coins', 'challenge', 'easy'] },
  { id: '49', title: 'Windfall Savings Rule', emoji: '🎁', content: 'Got a gift, bonus, tax refund, or unexpected money? Save at least 50% immediately. Treat the other 50% as fun money. This builds wealth from "surprise" income you weren\'t counting on.', category: 'saving', difficulty: 'beginner', potentialSaving: 1000, actionSteps: ['When you receive unexpected money, pause', 'Transfer 50% to savings immediately', 'Enjoy the other 50% guilt-free', 'Never spend 100% of windfalls'], tags: ['windfall', 'unexpected', 'habit'] },
  { id: '50', title: 'No-Spend Weekdays', emoji: '🚫', content: 'Challenge: spend R0 on weekdays (excluding fixed bills). Bring lunch, skip coffee shops, use campus resources. Save weekday money for weekend fun. This alone saves R1,000+/month.', category: 'saving', difficulty: 'intermediate', potentialSaving: 1000, actionSteps: ['Prep all weekday meals on Sunday', 'Make coffee at home', 'Use campus Wi-Fi and resources', 'Track your weekday spending streak'], tags: ['challenge', 'discipline', 'weekday'] },
  { id: '51', title: 'Savings Accountability Partner', emoji: '🤝', content: 'Share your savings goals with a trusted friend. Check in weekly. People with accountability partners are 65% more likely to reach their goals vs doing it alone.', category: 'saving', difficulty: 'beginner', potentialSaving: 600, actionSteps: ['Choose a trustworthy partner', 'Share specific savings goals', 'Schedule weekly check-ins', 'Celebrate milestones together'], tags: ['social', 'accountability', 'motivation'] },
  { id: '52', title: 'The 1% Increase Method', emoji: '📈', content: 'Increase your savings rate by 1% each month. If you save 5% now, next month save 6%, then 7%. By year end you\'re at 17%. It\'s so gradual you barely feel the change.', category: 'saving', difficulty: 'beginner', potentialSaving: 800, actionSteps: ['Calculate your current savings rate', 'Increase by 1% next month', 'Continue each month', 'Adjust spending gradually'], tags: ['gradual', 'habit', 'long-term'] },
  { id: '53', title: 'Sinking Funds', emoji: '🏖️', content: 'Save monthly for known future expenses: holiday (R500/mo for 6 months = R3,000), new phone (R300/mo for 10 months = R3,000). When the time comes, pay cash — no debt needed.', category: 'saving', difficulty: 'intermediate', potentialSaving: 1200, actionSteps: ['List all upcoming big expenses', 'Divide each by months until needed', 'Create separate savings pockets', 'Automate monthly contributions'], tags: ['planning', 'goals', 'no-debt'] },
  { id: '54', title: 'The 52-Week Challenge', emoji: '🗓️', content: 'Week 1: save R10. Week 2: R20. Week 3: R30... By week 52: R520. Total saved: R13,780 in one year. Start in January. If that\'s too much, do the reverse: start at R520 and decrease.', category: 'saving', difficulty: 'intermediate', potentialSaving: 13780, actionSteps: ['Start with R10 in week 1', 'Add R10 each week', 'Track on a printable chart', 'Consider starting high and going down if cash-strapped later'], tags: ['challenge', 'systematic', 'annual'] },
  { id: '55', title: 'Digital Detox Savings', emoji: '📵', content: 'Unsubscribe from marketing emails, delete shopping apps from your phone, unfollow brands on social media. Out of sight = out of mind = out of your wallet. Your phone is the biggest spending trigger.', category: 'saving', difficulty: 'beginner', potentialSaving: 800, actionSteps: ['Unsubscribe from all retail newsletters', 'Delete shopping apps', 'Unfollow brand accounts', 'Block ad-heavy websites'], tags: ['digital', 'mindset', 'temptation'] },
  { id: '56', title: 'Meal Replacement Math', emoji: '🥤', content: 'Replacing 2 bought meals/day with home-cooked ones saves R60-R120/day = R1,800-R3,600/month. That\'s R21,600-R43,200/year. Cooking is literally the highest-ROI skill a student can learn.', category: 'saving', difficulty: 'beginner', potentialSaving: 2000, actionSteps: ['Calculate what you spend on bought meals', 'Learn 5 cheap, easy recipes', 'Prep ingredients on weekends', 'Track savings from cooking at home'], tags: ['food', 'cooking', 'high-impact'] },
  { id: '57', title: 'Loyalty Program Stacking', emoji: '⭐', content: 'Checkers Xtra Savings, Pick n Pay Smart Shopper, Clicks ClubCard, Discovery Vitality. Stack loyalty programs to save 5-15% on groceries and health products. It\'s free money — just scan your card.', category: 'saving', difficulty: 'beginner', potentialSaving: 400, actionSteps: ['Sign up for all major loyalty programs', 'Scan your card at every purchase', 'Check for personalized offers in apps', 'Use loyalty points strategically'], tags: ['loyalty', 'groceries', 'free'] },
  { id: '58', title: 'Water Savings Strategy', emoji: '💧', content: 'SA water is getting expensive. Shorter showers (5 min vs 10 min) save 50L/day. Fix dripping taps immediately (10L/day wasted). Wash full loads only. Small changes = R100-R300/month saved.', category: 'saving', difficulty: 'beginner', potentialSaving: 300, actionSteps: ['Time your showers — aim for 5 minutes', 'Report/fix dripping taps', 'Only run full washing machine loads', 'Collect grey water for plants'], tags: ['utilities', 'water', 'environment'] },

  // === EARNING (59-75) ===
  { id: '59', title: 'Side Hustle Starter Pack', emoji: '💼', content: 'Tutoring: R150-R300/hr. Freelance design: R200+/hr. Pick something that builds skills in your field. 10hrs/week × R200/hr = R8,000/month extra.', category: 'earning', difficulty: 'intermediate', potentialSaving: 3000, actionSteps: ['Identify your top 3 marketable skills', 'Create a portfolio or WhatsApp Business profile', 'Start on Fiverr, Upwork, or campus boards', 'Dedicate 5-10 hrs/week'], tags: ['income', 'skill-building', 'freelance'] },
  { id: '60', title: 'Campus Job Opportunities', emoji: '🏢', content: 'Universities hire tutors (R80-R150/hr), lab assistants (R60-R100/hr), library assistants (R50-R70/hr), res mentors (free accommodation + stipend). Apply at your faculty office.', category: 'earning', difficulty: 'beginner', potentialSaving: 2000, actionSteps: ['Visit student employment office', 'Check faculty boards for tutor positions', 'Apply to be a res mentor', 'Ask lecturers about research assistantships'], tags: ['campus', 'part-time', 'CV-building'] },
  { id: '61', title: 'Sell What You Don\'t Use', emoji: '🛍️', content: 'The average student has R2,000-R5,000 in unused items. Facebook Marketplace, Gumtree, campus groups, Yaga. One weekend declutter session can fund a month of savings.', category: 'earning', difficulty: 'beginner', potentialSaving: 2500, actionSteps: ['Pile up everything unused for 3+ months', 'Photograph in good lighting', 'List on Facebook Marketplace & campus groups', 'Put proceeds straight into savings'], tags: ['declutter', 'quick-cash', 'easy'] },
  { id: '62', title: 'Build a Digital Skill', emoji: '💻', content: 'Learn free: Python (freeCodeCamp), design (Canva), video editing (DaVinci Resolve), data analysis (Google certificates). 3-6 months → R5,000-R20,000/month freelance income.', category: 'earning', difficulty: 'intermediate', potentialSaving: 5000, actionSteps: ['Pick ONE skill aligned with interests', 'Complete a free online course', 'Build 3 portfolio projects', 'Offer services at 50% market rate initially'], tags: ['skills', 'long-term', 'high-value'] },
  { id: '63', title: 'Content Creation as Income', emoji: '🎥', content: 'SA micro-influencers (5K-20K followers) earn R500-R5,000 per brand post. Pick a niche (student life, finance, tech), post consistently, monetise at 1K+ followers.', category: 'earning', difficulty: 'advanced', potentialSaving: 4000, actionSteps: ['Choose your platform and niche', 'Create 30 pieces before expecting results', 'Post 3-5x per week', 'Reach out to small SA brands at 1K followers'], tags: ['social-media', 'creative', 'passive-income'] },
  { id: '64', title: 'Online Surveys & Testing', emoji: '📋', content: 'UserTesting pays $10-60 per test (R180-R1,100). Respondent.io pays for research studies. Not life-changing money, but R500-R2,000/month in spare time is real.', category: 'earning', difficulty: 'beginner', potentialSaving: 1000, actionSteps: ['Sign up for UserTesting.com', 'Join Respondent.io', 'Complete profile surveys honestly', 'Check for new studies daily'], tags: ['easy', 'spare-time', 'online'] },
  { id: '65', title: 'Freelance Writing', emoji: '✍️', content: 'SA companies pay R0.50-R2.00 per word for content. A 1,000-word article = R500-R2,000. Academic writing skills transfer perfectly. Start on platforms like WriterAccess or directly pitch SA companies.', category: 'earning', difficulty: 'intermediate', potentialSaving: 3000, actionSteps: ['Create writing samples (3-5 pieces)', 'Sign up for freelance platforms', 'Pitch local companies directly', 'Build a portfolio website'], tags: ['writing', 'freelance', 'creative'] },
  { id: '66', title: 'Photography Side Gig', emoji: '📸', content: 'A decent smartphone is all you need to start. Event photography (R500-R2,000/event), product photography for small businesses (R300-R1,000/session), graduation photos on campus.', category: 'earning', difficulty: 'intermediate', potentialSaving: 2000, actionSteps: ['Practice photography skills', 'Build a portfolio on Instagram', 'Offer services to friends first', 'Market to campus events and small businesses'], tags: ['creative', 'events', 'photography'] },
  { id: '67', title: 'Delivery Driver Side Income', emoji: '🚗', content: 'Mr D, Uber Eats, Bolt Food: earn R50-R100/hour during peak times. If you have a car, scooter, or even bicycle, you can earn R2,000-R5,000/month working 10-15 hours/week.', category: 'earning', difficulty: 'beginner', potentialSaving: 3000, actionSteps: ['Sign up for delivery platforms', 'Work during peak hours (lunch & dinner)', 'Track fuel costs to calculate real earnings', 'Combine with other errands'], tags: ['delivery', 'flexible', 'gig-economy'] },
  { id: '68', title: 'Peer Tutoring Business', emoji: '👨‍🏫', content: 'Charge R150-R300/hr for subjects you excel at. 5 students × 1hr/week = R750-R1,500/week. Advertise on campus boards, WhatsApp groups. Build a reputation — referrals will follow.', category: 'earning', difficulty: 'intermediate', potentialSaving: 4000, actionSteps: ['Identify subjects you\'re strong in', 'Set competitive rates', 'Advertise on campus and online', 'Get student testimonials'], tags: ['tutoring', 'academic', 'campus'] },
  { id: '69', title: 'Social Media Management', emoji: '📲', content: 'Small businesses need social media help. Charge R1,500-R5,000/month per client for posting 3-5x/week. 2-3 clients = R3,000-R15,000/month. You already know social media — monetise it.', category: 'earning', difficulty: 'intermediate', potentialSaving: 5000, actionSteps: ['Learn basics of social media strategy', 'Create sample content for a made-up brand', 'Pitch to local small businesses', 'Use scheduling tools to be efficient'], tags: ['social-media', 'business', 'recurring'] },
  { id: '70', title: 'Graphic Design Freelancing', emoji: '🎨', content: 'Canva + basic design skills = R200-R500 per design. Logos, social media posts, flyers for local businesses. Fiverr, 99designs, or direct outreach to SA small businesses.', category: 'earning', difficulty: 'intermediate', potentialSaving: 3000, actionSteps: ['Master Canva or learn Figma (free)', 'Create a portfolio of 10+ designs', 'List services on Fiverr', 'Pitch to local businesses directly'], tags: ['design', 'creative', 'freelance'] },
  { id: '71', title: 'Rent Out What You Own', emoji: '🏷️', content: 'Have a parking spot? Rent it (R500-R1,500/mo). Extra room? Airbnb it during holidays. Even renting tools, textbooks, or equipment can generate passive income.', category: 'earning', difficulty: 'intermediate', potentialSaving: 1500, actionSteps: ['Inventory what you can rent out', 'Research prices in your area', 'List on appropriate platforms', 'Set clear terms and conditions'], tags: ['passive-income', 'rental', 'assets'] },
  { id: '72', title: 'Virtual Assistant Work', emoji: '🖥️', content: 'Email management, scheduling, data entry, research: VA work pays R80-R200/hour. Work remotely on your own schedule. SA VAs are in demand globally because of timezone and English skills.', category: 'earning', difficulty: 'beginner', potentialSaving: 3000, actionSteps: ['Learn basic VA skills (email, calendars, tools)', 'Create a professional profile', 'Apply on Belay, Time Etc, or Upwork', 'Start with one client and grow'], tags: ['remote', 'flexible', 'admin'] },
  { id: '73', title: 'Selling Notes & Study Guides', emoji: '📝', content: 'Platforms like Stuvia and OneClass let you sell your lecture notes. Well-organized notes for popular courses can earn R50-R200 per download. Passive income from work you\'re already doing.', category: 'earning', difficulty: 'beginner', potentialSaving: 1000, actionSteps: ['Take organized, typed notes', 'Upload to Stuvia or OneClass', 'Share links in course WhatsApp groups', 'Update notes each semester'], tags: ['passive-income', 'academic', 'easy'] },
  { id: '74', title: 'Event Photography & Videography', emoji: '🎬', content: 'Campus events, society functions, parties — all need photographers. Charge R500-R2,000 per event. Build portfolio on Instagram. Word of mouth in student communities is powerful.', category: 'earning', difficulty: 'intermediate', potentialSaving: 2000, actionSteps: ['Attend events to build portfolio', 'Offer first events at discount', 'Create an Instagram portfolio', 'Network with event organizers'], tags: ['events', 'creative', 'networking'] },
  { id: '75', title: 'Referral & Cashback Programs', emoji: '💸', content: 'FNB eBucks, Discovery Miles, Capitec rewards, TymeBank cashback. Plus: referral bonuses (TymeBank R50/referral, FNB eBucks R100). Refer 20 friends = R1,000-R2,000 for free.', category: 'earning', difficulty: 'beginner', potentialSaving: 1000, actionSteps: ['Check all your bank reward programs', 'Share referral links with friends', 'Use cashback credit cards for regular purchases', 'Stack rewards with loyalty cards'], tags: ['cashback', 'referral', 'passive'] },

  // === INVESTING (76-88) ===
  { id: '76', title: 'Start Investing with R100', emoji: '📈', content: 'EasyEquities lets you invest from R100. Satrix Top 40 tracks SA\'s biggest companies. Historical return: ~12%/year. R500/month from age 20 at 12% = R3.5 million by age 50.', category: 'investing', difficulty: 'intermediate', potentialSaving: 1200, actionSteps: ['Open EasyEquities account (10 mins)', 'Start with Satrix Top 40 ETF', 'Set up R100-R500 monthly auto-invest', 'Don\'t panic sell during dips'], tags: ['wealth-building', 'long-term', 'ETFs'] },
  { id: '77', title: 'Tax-Free Savings Account', emoji: '🏦', content: 'R36,000/year, R500K lifetime limit. ALL growth is tax-free. R3,000/mo from age 22 to 30 in a TFSA earning 12% = R500K+ that grows tax-free forever. The most powerful tool for young South Africans.', category: 'investing', difficulty: 'advanced', potentialSaving: 3000, actionSteps: ['Open a TFSA at EasyEquities or Satrix', 'Choose a low-cost equity ETF', 'Contribute R500-R3,000/month', 'NEVER withdraw — let compounding work'], tags: ['tax', 'wealth-building', 'essential'] },
  { id: '78', title: 'Understand Compound Interest', emoji: '🧮', content: 'R1,000 at 12%/year: 10 years = R3,106. 20 years = R9,646. 30 years = R29,960. Starting at 20 vs 30 = 3-5x more wealth at retirement. Einstein called it the 8th wonder of the world.', category: 'investing', difficulty: 'beginner', potentialSaving: 2000, actionSteps: ['Use a compound interest calculator', 'Compare starting now vs in 5 years', 'Even R100/month matters — just start', 'Reinvest all returns'], tags: ['fundamentals', 'long-term', 'wealth'] },
  { id: '79', title: 'Avoid Investment Scams', emoji: '⚠️', content: 'Guaranteed returns above 15-20%? Likely a scam. Red flags: "guaranteed" returns, recruit-others pressure, unregistered with FSCA. MMM, Kipi — billions stolen. Stick to regulated platforms.', category: 'investing', difficulty: 'beginner', potentialSaving: 5000, actionSteps: ['Check FSCA registration for any investment', 'If returns are "guaranteed" and high, it\'s a scam', 'Stick to regulated platforms', 'Report scams to FSCA: 0800 110 443'], tags: ['safety', 'scams', 'critical'] },
  { id: '80', title: 'Global vs Local Investing', emoji: '🌍', content: 'The rand weakens ~5%/year vs dollar long-term. Invest offshore to protect against depreciation. Satrix MSCI World ETF gives exposure to Apple, Google, Amazon via SA brokerage.', category: 'investing', difficulty: 'advanced', potentialSaving: 2000, actionSteps: ['Allocate 40-60% to global ETFs', 'Use Satrix MSCI World or 1nvest S&P 500', 'Keep some SA exposure', 'Rebalance once per year'], tags: ['diversification', 'offshore', 'advanced'] },
  { id: '81', title: 'Dollar-Cost Averaging', emoji: '📊', content: 'Invest the same amount every month regardless of market conditions. This means you buy more when prices are low, less when high. Over time, this outperforms trying to time the market.', category: 'investing', difficulty: 'intermediate', potentialSaving: 1500, actionSteps: ['Set a fixed monthly investment amount', 'Automate it on the same day each month', 'Ignore short-term market movements', 'Review annually, not monthly'], tags: ['strategy', 'systematic', 'long-term'] },
  { id: '82', title: 'Understanding ETFs', emoji: '📦', content: 'ETFs (Exchange-Traded Funds) are baskets of stocks. One ETF = instant diversification. Fees: 0.1-0.5% vs mutual funds at 1-3%. Lower fees = more money in your pocket long-term.', category: 'investing', difficulty: 'beginner', potentialSaving: 1000, actionSteps: ['Learn what an ETF is (YouTube: "ETF explained")', 'Compare ETF fees on EasyEquities', 'Start with a broad market ETF', 'Avoid sector-specific ETFs at first'], tags: ['ETFs', 'basics', 'diversification'] },
  { id: '83', title: 'Retirement Annuity for Tax Benefits', emoji: '🏛️', content: 'Contributions to an RA are tax-deductible up to 27.5% of taxable income. If you earn R10,000/mo, R2,750/mo is tax-deductible = save R500+/mo in tax. Start early and benefit from decades of growth.', category: 'investing', difficulty: 'advanced', potentialSaving: 3000, actionSteps: ['Understand the tax benefit', 'Start with minimum contributions', 'Choose a low-cost RA provider (10X, Sygnia)', 'Increase contributions with income'], tags: ['tax', 'retirement', 'long-term'] },
  { id: '84', title: 'Investment Fees Matter', emoji: '💸', content: '1% fee difference over 30 years can cost you 25% of your wealth. R500/mo at 12% for 30 years: 0.5% fees = R1.4M. 2.5% fees = R900K. That\'s R500K lost to fees. Always check total expense ratios.', category: 'investing', difficulty: 'intermediate', potentialSaving: 2000, actionSteps: ['Check TER (Total Expense Ratio) of your investments', 'Compare similar funds by fee', 'Choose lowest-cost option', 'Avoid actively managed funds unless they consistently beat index'], tags: ['fees', 'costs', 'optimization'] },
  { id: '85', title: 'Stock Market Basics', emoji: '📉', content: 'The JSE has returned ~14%/year since 1960. Bear markets (drops of 20%+) happen every 5-7 years but always recover. If you invest for 10+ years, your probability of positive returns is 95%+.', category: 'investing', difficulty: 'beginner', potentialSaving: 1500, actionSteps: ['Learn basic market terminology', 'Understand: stocks, bonds, ETFs, dividends', 'Start with ETFs, not individual stocks', 'Think in decades, not days'], tags: ['basics', 'JSE', 'long-term'] },
  { id: '86', title: 'Crypto Caution', emoji: '₿', content: 'Crypto is high-risk, high-reward. Never invest more than 5-10% of your portfolio. Use regulated SA exchanges (Luno, VALR). Don\'t follow TikTok crypto advice. Most day traders lose money.', category: 'investing', difficulty: 'advanced', potentialSaving: 1000, actionSteps: ['Only use regulated SA exchanges', 'Never invest more than you can lose', 'Learn before investing — not after', 'Avoid meme coins and "guaranteed" returns'], tags: ['crypto', 'high-risk', 'caution'] },
  { id: '87', title: 'Real Estate Investment Trusts', emoji: '🏢', content: 'Can\'t afford property? REITs let you invest in real estate from R100. Growthpoint, Redefine, Fortress on the JSE. They pay dividends quarterly and give property exposure without a bond.', category: 'investing', difficulty: 'intermediate', potentialSaving: 1000, actionSteps: ['Research SA REITs on EasyEquities', 'Start with established REITs', 'Reinvest dividends', 'Hold long-term for growth + income'], tags: ['property', 'REITs', 'dividends'] },
  { id: '88', title: 'Investment Portfolio Rebalancing', emoji: '⚖️', content: 'Once a year, check if your asset allocation has drifted. If stocks grew to 80% but your target is 60%, sell some and buy bonds. This systematically buys low and sells high.', category: 'investing', difficulty: 'advanced', potentialSaving: 800, actionSteps: ['Set target allocation (e.g., 60% equity, 40% bonds)', 'Review once per year', 'Rebalance if off by more than 5%', 'Use new contributions to rebalance naturally'], tags: ['rebalancing', 'portfolio', 'annual'] },

  // === LIFESTYLE (89-105) ===
  { id: '89', title: 'The No-Spend Challenge', emoji: '🚫', content: 'Pick one day per week with R0 spending. Bring lunch, skip coffee shops, walk instead of Uber. Monthly savings: R500-R1,000. Yearly: R6,000-R12,000. Retrains your brain for free alternatives.', category: 'lifestyle', difficulty: 'beginner', potentialSaving: 800, actionSteps: ['Choose your no-spend day', 'Prep meals the night before', 'Find free entertainment', 'Challenge friends to join'], tags: ['challenge', 'mindset', 'weekly'] },
  { id: '90', title: 'The 24-Hour Rule', emoji: '⏰', content: 'Before any non-essential purchase over R200, wait 24 hours. This eliminates 70% of impulse purchases. For items over R1,000, wait a full week.', category: 'lifestyle', difficulty: 'beginner', potentialSaving: 1500, actionSteps: ['Add to cart but don\'t checkout', 'Write the item in your notes', 'Set a 24-hour timer', 'Ask: need or want?'], tags: ['mindset', 'impulse-control', 'psychology'] },
  { id: '91', title: 'Free Entertainment Guide (SA)', emoji: '🎭', content: 'Joburg: Constitution Hill, Zoo Lake, Delta Park. Cape Town: Kirstenbosch free Tuesdays, Sea Point, Bo-Kaap. Durban: beachfront, Moses Mabhida. Amazing weekends cost R0.', category: 'lifestyle', difficulty: 'beginner', potentialSaving: 600, actionSteps: ['List free activities in your city', 'Plan 2 free activities per weekend', 'Follow local "free events" pages', 'Explore nature — hiking is free and amazing in SA'], tags: ['fun', 'free', 'social'] },
  { id: '92', title: 'Coffee Shop Math', emoji: '☕', content: 'R45 cappuccino daily = R11,880/year. French press at home = R1,560/year. That R10,320 invested at 12% = R185,000 over 10 years. Your daily coffee could buy a car.', category: 'lifestyle', difficulty: 'beginner', potentialSaving: 10000, actionSteps: ['Buy a French press (R200)', 'Buy quality beans from local roasters', 'Make coffee at home on weekdays', 'Invest the R800/month difference'], tags: ['latte-factor', 'daily-habit', 'high-impact'] },
  { id: '93', title: 'Social Media Spending Triggers', emoji: '🧠', content: 'Instagram ads and influencer marketing are designed to make you buy. 2+ hours daily = 30% more spending. Unfollow accounts that trigger spending. Follow finance accounts instead.', category: 'lifestyle', difficulty: 'beginner', potentialSaving: 1200, actionSteps: ['Unfollow "haul" accounts', 'Follow SA finance creators', 'Remove saved payment methods from apps', 'Screenshot ads and wait 7 days'], tags: ['psychology', 'social-media', 'awareness'] },
  { id: '94', title: 'Electricity & Water Savings', emoji: '💡', content: 'Shorter showers: R200/mo saved. LED bulbs: R100/mo. Geyser timer: R300/mo. Unplug chargers: R50/mo. Cook with lids: 30% faster. Combined: R500-R800/month.', category: 'lifestyle', difficulty: 'beginner', potentialSaving: 700, actionSteps: ['Install a geyser timer', 'Replace bulbs with LEDs', 'Time showers (5 minutes)', 'Unplug everything not in use'], tags: ['utilities', 'daily', 'environment'] },
  { id: '95', title: 'Health on a Budget', emoji: '🏃', content: 'YouTube workouts (free) > R700/month gym. Planet Fitness: R99/mo. University gym: often free. Frozen veggies are just as nutritious as fresh but 50% cheaper.', category: 'lifestyle', difficulty: 'beginner', potentialSaving: 500, actionSteps: ['Check for free campus gym', 'Try YouTube HIIT workouts', 'Buy frozen vegetables', 'Drink water instead of sugary drinks'], tags: ['health', 'fitness', 'nutrition'] },
  { id: '96', title: 'Bulk Buying Strategy', emoji: '🛒', content: 'Non-perishables in bulk save 20-40%. Makro, Jumbo Cash & Carry. Split with flatmates: 10kg rice, 5L cooking oil. Track price per unit, not total price.', category: 'lifestyle', difficulty: 'beginner', potentialSaving: 600, actionSteps: ['List items used monthly', 'Compare bulk vs regular unit prices', 'Split purchases with friends', 'Stock up during sales'], tags: ['groceries', 'shopping', 'smart-buying'] },
  { id: '97', title: 'Insurance You Actually Need', emoji: '🔐', content: 'Students probably DON\'T need life insurance. DO need: phone insurance (R70-R150/mo) if phone costs R5K+, laptop insurance (R50-R100/mo). Use Hippo.co.za to compare. Don\'t over-insure.', category: 'lifestyle', difficulty: 'intermediate', potentialSaving: 800, actionSteps: ['List what you have insured', 'Ask: can I replace this myself?', 'If yes, skip the premium', 'Shop around for what you actually need'], tags: ['insurance', 'protection', 'adulting'] },
  { id: '98', title: 'DIY Repairs & Maintenance', emoji: '🔧', content: 'YouTube can teach you to fix almost anything: leaking taps, torn clothing, cracked phone screens. A R50 DIY fix beats a R500 repair bill every time. Learning basic repairs is an investment.', category: 'lifestyle', difficulty: 'intermediate', potentialSaving: 500, actionSteps: ['Before calling a professional, YouTube it', 'Build a basic toolkit (R200-R300)', 'Learn to sew basic stitches', 'Fix small things immediately before they worsen'], tags: ['DIY', 'maintenance', 'skills'] },
  { id: '99', title: 'Travel Hacking for SA Students', emoji: '✈️', content: 'Kulula and FlySafair run R500-R800 one-way flash sales. Follow them on social media. Book 6-8 weeks ahead. BlaBlaCar and lift clubs for intercity travel are 50-70% cheaper than flights.', category: 'lifestyle', difficulty: 'intermediate', potentialSaving: 1500, actionSteps: ['Follow Kulula/FlySafair on social media', 'Set price alerts', 'Book 6-8 weeks in advance', 'Use BlaBlaCar for nearby cities'], tags: ['travel', 'deals', 'adventure'] },
  { id: '100', title: 'Mindful Spending Practice', emoji: '🧘', content: 'Before every purchase, pause 5 seconds and ask: "Does this align with my goals?" This tiny habit redirects thousands of rands from impulse buys to things that matter.', category: 'lifestyle', difficulty: 'beginner', potentialSaving: 1000, actionSteps: ['Create a 1-sentence financial goal', 'Write it on your phone lock screen', 'Pause before every purchase', 'Ask: does this serve my goal?'], tags: ['mindfulness', 'intentional', 'habit'] },
  { id: '101', title: 'Declutter for Cash', emoji: '🧹', content: 'Every 3 months, do a room audit. Anything unused goes on Facebook Marketplace. Most people accumulate R1,000-R3,000 in sellable items every quarter without realizing it.', category: 'lifestyle', difficulty: 'beginner', potentialSaving: 1500, actionSteps: ['Schedule quarterly declutter days', 'Be honest about what you use', 'Photograph and list items', 'Price competitively for quick sales'], tags: ['declutter', 'income', 'quarterly'] },
  { id: '102', title: 'Gratitude & Money Mindset', emoji: '🙏', content: 'Gratitude reduces spending. People who practice gratitude spend 20% less on non-essentials. Each morning, write 3 things you\'re grateful for. It shifts focus from what you lack to what you have.', category: 'lifestyle', difficulty: 'beginner', potentialSaving: 600, actionSteps: ['Start a gratitude journal', 'Write 3 things each morning', 'Notice how it affects spending urges', 'Share gratitude with friends'], tags: ['mindset', 'psychology', 'wellness'] },
  { id: '103', title: 'Cook One New Recipe Weekly', emoji: '👨‍🍳', content: 'Expanding your recipe repertoire makes meal prep exciting instead of boring. One new recipe per week = 52 by year end. You\'ll never be tempted by takeaways again.', category: 'lifestyle', difficulty: 'beginner', potentialSaving: 400, actionSteps: ['Pick one new recipe each weekend', 'Try cuisines you\'ve never cooked', 'Use budget-friendly ingredients', 'Share with flatmates'], tags: ['cooking', 'food', 'habit'] },
  { id: '104', title: 'Energy Audit Your Space', emoji: '⚡', content: 'Track electricity usage for a month. Identify biggest consumers: geysers (40%), stoves, heaters. Switch to gas cooking (50% cheaper), use blankets vs heaters, solar-powered phone chargers.', category: 'lifestyle', difficulty: 'intermediate', potentialSaving: 600, actionSteps: ['Track electricity spend monthly', 'Identify top 3 energy consumers', 'Switch to energy-efficient alternatives', 'Compare electricity use month-over-month'], tags: ['energy', 'electricity', 'loadshedding'] },
  { id: '105', title: 'Financial Literacy Reading List', emoji: '📖', content: 'Free books that change your money mindset: Rich Dad Poor Dad (library), The Richest Man in Babylon (free PDF), Manage Your Money Like a F*cking Grownup (SA author Sam Beckbessinger). Knowledge = wealth.', category: 'lifestyle', difficulty: 'beginner', potentialSaving: 500, actionSteps: ['Read one financial book per month', 'Start with Sam Beckbessinger\'s SA book', 'Join a money-focused book club', 'Apply one lesson from each book'], tags: ['education', 'reading', 'knowledge'] },
];
